/* GALE — thunderstorm theme (storm-black sky / lightning bolt / electric
   blue / storm purple / gale-warning red). The fleet's names are all wind
   and storm — the palette now is too: near-black storm sky, electric
   lightning accents, occasional flash. No build step: static HTML + one
   stylesheet + vanilla ES modules.
   Everything degrades: no-JS still shows all content; reduced motion
   collapses every animation through the global kill-switch at the bottom. */

/* ---- design tokens ---- */
:root {
  --bg: #05070d;
  --bg-deep: #030409;
  --surface: #0d1120;
  --surface-2: #131a2c;
  --glass: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(160, 185, 230, 0.1);
  --line: rgba(160, 185, 230, 0.08);
  --line-strong: rgba(160, 185, 230, 0.18);
  --text: #e4eaf4;
  --text-dim: #92a2bc;

display.text:
/* GALE — thunderstorm theme (storm-black sky / lightning bolt / electric
   blue / storm purple / gale-warning red). The fleet's names are all wind
   and storm — the palette now is too: near-black storm sky, electric
   lightning accents, occasional flash. No build step: static HTML + one
   stylesheet + vanilla ES modules.
   Everything degrades: no-JS still shows all content; reduced motion
   collapses every animation through the global kill-switch at the bottom. */

/* ---- design tokens ---- */
:root {
  --bg: #05070d;
  --bg-deep: #030409;
  --surface: #0d1120;
  --surface-2: #131a2c;
  --glass: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(160, 185, 230, 0.1);
  --line: rgba(160, 185, 230, 0.08);
  --line-strong: rgba(160, 185, 230, 0.18);
  --text: #e4eaf4;
  --text-dim: #92a2bc;
  --text-faint: #5e6c84;
  --flag: #e8482c;
  --flag-soft: #ff7a5c;
  --flag-dim: rgba(232, 72, 44, 0.32);
  --bolt: #ffd23f;
  --bolt-bright: #ffe97a;
  --bolt-dim: rgba(255, 210, 63, 0.35);
  --gust: #6ea6ff;
  --gust-dim: rgba(110, 166, 255, 0.3);
  --storm-purple: #9b8cff;
  --storm-purple-dim: rgba(155, 140, 255, 0.3);
  --ok: #4fae7a;
  --ok-dim: rgba(79, 174, 122, 0.3);
  --warn: #f0a83c;
  --warn-dim: rgba(240, 168, 60, 0.3);
  --m-claude: #ffc233;
  --m-glm: #ff2ec4;
  --m-gpt: #ff5a5f;
  --m-muse: #9dff3d;
  --font-heading: "Fraunces", Georgia, serif;
  --font-body: "Inter", -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", "IBM Plex Mono", ui-monospace, monospace;
  --ease-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out: cubic-bezier(0.22, 0.61, 0.36, 1);
  --wrap: 1080px;
  --narrow: 720px;
}

@property --shine-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

/* ---- base ---- */
* { box-sizing: border-box; }

html {
  color-scheme: dark;
  scrollbar-color: #26334a transparent;
}

@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

body {
  margin: 0;
  background: var(--bg-deep);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  overflow-x: clip;
}

::selection { background: color-mix(in srgb, var(--flag) 40%, transparent); }

:where(a, button, [tabindex]):focus-visible {
  outline: 2px solid var(--gust);
  outline-offset: 3px;
  border-radius: 4px;
}

a { color: var(--gust); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: color-mix(in srgb, var(--gust) 40%, transparent); }
a:hover { text-decoration-color: var(--gust); }

img, svg { display: block; max-width: 100%; }
code { font-family: var(--font-mono); font-size: 0.85em; color: var(--gust); }

.wrap { max-width: var(--wrap); margin-inline: auto; padding-inline: clamp(20px, 4vw, 36px); }

.skip {
  position: absolute; left: -999px; top: 10px; z-index: 200;
  background: var(--surface-2); color: var(--text); padding: 8px 14px;
  border: 1px solid var(--glass-border); border-radius: 8px; font-size: 0.85rem;
}
.skip:focus { left: 12px; }

/* ---- atmosphere: storm sky, rain grid, lightning flash, drifting clouds ---- */
body::before {
  content: "";
  position: fixed; inset: 0; z-index: -3; pointer-events: none;
  background:
    radial-gradient(ellipse 90% 55% at 50% -8%, color-mix(in srgb, var(--storm-purple) 8%, transparent), transparent 62%),
    radial-gradient(ellipse 60% 40% at 85% 110%, color-mix(in srgb, var(--flag) 6%, transparent), transparent 60%),
    linear-gradient(rgba(200, 215, 240, 0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(200, 215, 240, 0.022) 1px, transparent 1px),
    var(--bg-deep);
  background-size: auto, auto, 64px 64px, 64px 64px, auto;
}

/* lightning flash: a bolt-wash over the whole sky, rare and brief */
body::after {
  content: "";
  position: fixed; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(ellipse 70% 34% at 18% 0%, rgba(255, 244, 214, 0.5), transparent 55%),
    radial-gradient(ellipse 55% 28% at 78% 4%, rgba(190, 214, 255, 0.35), transparent 60%);
  opacity: 0;
  mix-blend-mode: screen;
  animation: lightning-flash 13s linear infinite;
}

@keyframes lightning-flash {
  0%, 88.9%, 91.2%, 94%, 100% { opacity: 0; }
  89.2% { opacity: 0.5; }
  89.9% { opacity: 0.08; }
  90.6% { opacity: 0.75; }
  93% { opacity: 0.05; }
}

.blob {
  position: fixed; z-index: -2; pointer-events: none;
  border-radius: 50%; filter: blur(110px); opacity: 0.7;
}
.blob-red {
  width: 540px; height: 540px; left: -160px; top: -180px;
  background: color-mix(in srgb, var(--flag) 12%, transparent);
  animation: blob-a 26s ease-in-out infinite alternate;
}
.blob-blue {
  width: 620px; height: 620px; right: -220px; top: 22vh;
  background: color-mix(in srgb, var(--storm-purple) 10%, transparent);
  animation: blob-b 34s ease-in-out infinite alternate;
}
@keyframes blob-a { to { transform: translate(10vw, 8vh) scale(1.18); } }
@keyframes blob-b { to { transform: translate(-9vw, 10vh) scale(0.92); } }

#storm-canvas {
  position: fixed; inset: 0; z-index: -1;
  width: 100%; height: 100%; pointer-events: none;
}

/* ---- scroll progress: pure CSS scroll-driven timeline, JS fallback ---- */
#progress {
  position: fixed; top: 0; left: 0; right: 0; height: 2px; z-index: 120;
  transform: scaleX(var(--p, 0)); transform-origin: 0 50%;
  background: linear-gradient(90deg, var(--flag), var(--gust));
  pointer-events: none;
}
@supports (animation-timeline: scroll()) {
  @media (prefers-reduced-motion: no-preference) {
    #progress { animation: progress-grow linear both; animation-timeline: scroll(root); }
  }
}
@keyframes progress-grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
html.progress-js #progress { animation: none; }

/* ---- cross-page view transitions ---- */
@view-transition { navigation: auto; }
::view-transition-old(root), ::view-transition-new(root) { animation-duration: 200ms; }
header.site { view-transition-name: site-header; }
::view-transition-old(site-header), ::view-transition-new(site-header) { animation: none; }

/* ---- header ---- */
header.site {
  position: sticky; top: 0; z-index: 60;
  background: color-mix(in srgb, var(--bg) 76%, transparent);
  -webkit-backdrop-filter: blur(14px) saturate(1.25);
  backdrop-filter: blur(14px) saturate(1.25);
  border-bottom: 1px solid var(--line);
}
header.site .wrap { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-block: 15px; }
.brand {
  display: inline-flex; align-items: center; gap: 11px;
  font-family: var(--font-heading); font-weight: 600; font-size: 1.12rem;
  letter-spacing: 0.02em; color: var(--text); text-decoration: none;
}
.brand svg { flex: none; }
.brand:hover { text-decoration: none; }

nav.site-links {
  display: flex; gap: 22px; font-size: 0.9rem;
}
@media (max-width: 900px) {
  nav.site-links {
    overflow-x: auto; max-width: 60vw; scrollbar-width: none;
    -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 26px), transparent);
    mask-image: linear-gradient(90deg, #000 calc(100% - 26px), transparent);
  }
  nav.site-links::-webkit-scrollbar { display: none; }
}
nav.site-links a { color: var(--text-dim); text-decoration: none; white-space: nowrap; transition: color 0.2s; }
nav.site-links a:hover { color: var(--text); }
nav.site-links a[aria-current="page"] {
  color: var(--text); text-underline-offset: 6px;
  text-decoration: underline; text-decoration-color: var(--flag); text-decoration-thickness: 2px;
}

/* ---- conditions ticker ---- */
.ticker {
  border-block: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface) 60%, transparent);
  overflow: clip; white-space: nowrap;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);
}
.ticker-track {
  display: inline-flex; align-items: center; gap: 0;
  padding-block: 8px; width: max-content;
  animation: ticker-roll 44s linear infinite;
}
.ticker-half { display: inline-flex; align-items: center; }
.ticker-track span {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--font-mono); font-size: 0.74rem; letter-spacing: 0.09em;
  text-transform: uppercase; color: var(--text-dim); padding-inline: 1.6rem;
}
.ticker-track span::before {
  content: ""; width: 5px; height: 5px; border-radius: 1px;
  background: var(--flag); opacity: 0.7; transform: rotate(45deg);
}
@keyframes ticker-roll { to { transform: translateX(-50%); } }

/* ---- hero ---- */
.hero {
  position: relative;
  max-width: var(--wrap); margin-inline: auto;
  padding-block: clamp(64px, 9vw, 120px) clamp(40px, 6vw, 72px);
  padding-inline: clamp(20px, 4vw, 36px);
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 44%);
  gap: clamp(24px, 4vw, 56px); align-items: center;
}
.hero-solo { grid-template-columns: minmax(0, 1fr); max-width: 820px; }

@media (max-width: 860px) {
  .hero { grid-template-columns: minmax(0, 1fr); }
  .scene-wrap { max-width: 460px; }
}

.hero .eyebrow { justify-self: start; }

.eyebrow {
  display: inline-flex; align-items: center; gap: 9px;
  font-family: var(--font-mono); font-size: 0.74rem; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--flag-soft);
  border: 1px solid color-mix(in srgb, var(--flag) 45%, transparent);
  background: color-mix(in srgb, var(--flag) 10%, transparent);
  padding: 5px 13px; border-radius: 999px; margin-bottom: 26px;
}
.eyebrow .dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--flag);
  animation: dot-pulse 2.2s ease-in-out infinite;
}
@keyframes dot-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--flag) 55%, transparent); opacity: 1; }
  70% { box-shadow: 0 0 0 7px transparent; opacity: 0.6; }
}

h1.hero-title {
  font-family: var(--font-heading); font-weight: 600;
  font-size: clamp(2.05rem, 8.5vw, 4.1rem);
  line-height: 1.04; letter-spacing: -0.025em;
  margin: 0 0 22px; text-wrap: balance;
}
h1.hero-title .shine {
  background: linear-gradient(var(--shine-angle), var(--bolt-bright), var(--gust) 45%, var(--bolt-bright));
  background-size: 220% auto;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  animation: shine 9s linear infinite;
}
@keyframes shine { to { --shine-angle: 360deg; } }

/* line mask-reveal (from-only keyframes: no-JS still shows the text) */
.hline { display: block; overflow: clip; }
.hline > span {
  display: block;
  animation: h-rise 0.9s var(--ease-expo) both;
  animation-delay: calc(var(--i, 0) * 0.13s);
}
@keyframes h-rise { from { transform: translateY(112%); } }

.hero .lede {
  font-size: clamp(1.05rem, 1.9vw, 1.22rem); color: var(--text-dim);
  max-width: 58ch; margin: 0 0 18px; text-wrap: pretty;
}
.hero .meta-line {
  font-family: var(--font-mono); font-size: 0.78rem; color: var(--text-faint);
  letter-spacing: 0.02em;
}

.hero-stats { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 30px; }
.fleet-stat {
  display: flex; flex-direction: column; gap: 2px;
  background: var(--glass); border: 1px solid var(--glass-border);
  border-radius: 14px; padding: 13px 20px; min-width: 128px;
  transition: transform 0.25s var(--ease-out), border-color 0.25s;
}
.fleet-stat:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.fleet-stat-n { font-family: var(--font-heading); font-size: 1.65rem; font-weight: 600; line-height: 1.1; }
.fleet-stat-l { font-size: 0.78rem; color: var(--text-dim); }

/* ---- lighthouse scene ---- */
.scene-wrap { position: relative; }
.scene { width: 100%; height: auto; overflow: clip; border-radius: 20px; border: 1px solid var(--glass-border); background: transparent; }
.scene [data-depth] { will-change: transform; }

.scene .star { fill: #cfe2f4; animation: twinkle 3.4s ease-in-out infinite; animation-delay: calc(var(--i) * -0.9s); }
@keyframes twinkle { 0%, 100% { opacity: 0.25; } 50% { opacity: 0.95; } }

.scene .cloud { fill: #14202f; opacity: 0.95; animation: cloud-drift 44s ease-in-out infinite alternate; }
.scene .cloud.c2 { animation-duration: 58s; animation-delay: -20s; }
.scene .cloud.c3 { animation-duration: 36s; animation-delay: -8s; }
@keyframes cloud-drift { from { transform: translateX(-26px); } to { transform: translateX(30px); } }

.scene .flash { opacity: 0; animation: lightning 8.5s linear infinite; }
@keyframes lightning {
  0%, 91.5%, 94.5%, 100% { opacity: 0; }
  92% { opacity: 0.55; } 93% { opacity: 0.08; } 94% { opacity: 0.4; }
}
.scene .bolt { opacity: 0; animation: bolt-flicker 8.5s linear infinite; }
@keyframes bolt-flicker {
  0%, 91.4%, 94.6%, 100% { opacity: 0; }
  91.6% { opacity: 0.9; } 92.2% { opacity: 0.2; } 92.8% { opacity: 0.75; } 93.6% { opacity: 0; }
}

.scene .wave-a { animation: wave-roll 7s linear infinite; stroke: #2a4258; stroke-width: 1; }
.scene .wave-b { animation: wave-roll 11s linear infinite reverse; opacity: 0.8; }
@keyframes wave-roll { from { transform: translateX(0); } to { transform: translateX(-160px); } }

.scene .beam-group {
  transform-box: view-box; transform-origin: 470px 238px;
  animation: beam-sweep 24s linear infinite;
}
@keyframes beam-sweep { to { transform: rotate(360deg); } }
.scene .beam-l { fill: url(#beam-l); mix-blend-mode: screen; }
.scene .beam-r { fill: url(#beam-r); mix-blend-mode: screen; }

.scene .lamp-glow { animation: lamp-breathe 2.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
@keyframes lamp-breathe { 50% { opacity: 0.55; transform: scale(1.25); } }

.scene .signal-ring {
  fill: none; stroke: var(--flag); stroke-width: 1.1; opacity: 0;
  transform-box: fill-box; transform-origin: center;
  animation: signal 3.2s cubic-bezier(0, 0, 0.2, 1) infinite;
}
.scene .signal-ring.r2 { animation-delay: 1.05s; }
.scene .signal-ring.r3 { animation-delay: 2.1s; }
@keyframes signal {
  0% { transform: scale(0.25); opacity: 0.65; }
  70% { transform: scale(3.4); opacity: 0; }
  100% { transform: scale(3.4); opacity: 0; }
}

.scene .rain-line { stroke: #a9c8e4; stroke-width: 1; opacity: 0.14; stroke-dasharray: 22 34; animation: rain-fall 1.1s linear infinite; animation-delay: calc(var(--i) * -0.17s); }
.scene .rain-line.slow { animation-duration: 1.5s; opacity: 0.09; }
@keyframes rain-fall { to { stroke-dashoffset: -112; } }

/* ---- sections ---- */
section.block {
  max-width: var(--wrap); margin-inline: auto;
  padding-block: clamp(60px, 8vw, 104px);
  padding-inline: clamp(20px, 4vw, 36px);
}
h2.sec-title {
  font-family: var(--font-heading); font-weight: 600;
  font-size: clamp(1.65rem, 3.6vw, 2.25rem); letter-spacing: -0.02em;
  margin: 0 0 14px; text-wrap: balance;
  display: flex; align-items: center; gap: 16px;
}
h2.sec-title::before {
  content: ""; flex: none; width: 30px; height: 3px; border-radius: 2px;
  background: linear-gradient(90deg, var(--flag), transparent);
}
.sec-lede { color: var(--text-dim); max-width: 66ch; margin: 0 0 38px; font-size: 1.02rem; text-wrap: pretty; }

/* ---- stat cards: container-queried type, pointer glow, 3D tilt ---- */
.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.card {
  container-type: inline-size;
  position: relative; overflow: clip;
  background: linear-gradient(180deg, var(--glass), transparent 150%), var(--surface);
  border: 1px solid var(--glass-border); border-radius: 16px;
  padding: clamp(16px, 5cqw, 26px);
  transition: border-color 0.3s, box-shadow 0.3s;
  will-change: transform;
}
.card:hover { border-color: var(--line-strong); box-shadow: 0 18px 44px rgba(0, 0, 0, 0.35); }
.card::after {
  content: ""; position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(240px circle at var(--mx, 50%) var(--my, 50%),
    color-mix(in srgb, var(--flag) 13%, transparent), transparent 70%);
  transition: opacity 0.35s;
}
.card:hover::after { opacity: 1; }
.card .value {
  display: block; font-family: var(--font-heading); font-weight: 600;
  font-size: clamp(1.5rem, 9cqw, 2.3rem); line-height: 1.1; letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.card .label { display: block; margin-top: 7px; font-size: 0.82rem; color: var(--text-dim); line-height: 1.45; }
.card .trend { margin-top: 10px; font-family: var(--font-mono); font-size: 0.7rem; color: var(--ok); letter-spacing: 0.04em; }

@media (max-width: 900px) { .stat-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 460px) { .stat-grid { grid-template-columns: 1fr; } }

/* ---- wake cycle: static list fallback + scroll-scrubbed sticky stage ---- */
.wake-steps { list-style: none; margin: 0; padding: 0; max-width: var(--narrow); counter-reset: step; }
.wake-steps li {
  counter-increment: step; position: relative;
  padding: 22px 0 22px 58px; border-bottom: 1px solid var(--line);
  color: var(--text-dim); font-size: 0.98rem;
}
.wake-steps li:last-child { border-bottom: 0; }
.wake-steps li::before {
  content: "0" counter(step);
  position: absolute; left: 0; top: 24px;
  font-family: var(--font-mono); font-size: 0.8rem; color: var(--flag);
  border: 1px solid color-mix(in srgb, var(--flag) 40%, transparent);
  border-radius: 8px; padding: 2px 7px;
}
.wake-steps strong { display: block; color: var(--text); font-weight: 600; margin-bottom: 4px; font-size: 1.05rem; }

.wake-scrub { display: none; }
.scrub-live .wake-scrub { display: block; }
.scrub-live .wake-steps { display: none; }

.wake-track { height: 400vh; }
.wake-stage {
  position: sticky; top: 0; height: 100vh;
  display: grid; grid-template-columns: minmax(0, 46%) minmax(0, 1fr);
  align-items: center; gap: clamp(24px, 5vw, 72px);
  max-width: var(--wrap); margin-inline: auto; padding-inline: clamp(20px, 4vw, 36px);
}
.wake-copy-set { display: grid; }
.wake-copy { grid-area: 1 / 1; opacity: 0; transform: translateY(16px) scale(0.985); transition: opacity 0.5s var(--ease-out), transform 0.5s var(--ease-out); pointer-events: none; }
.wake-copy.on { opacity: 1; transform: none; }
.wake-copy .k {
  font-family: var(--font-mono); font-size: 0.74rem; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--flag); margin-bottom: 14px;
}
.wake-copy h3 {
  font-family: var(--font-heading); font-weight: 600;
  font-size: clamp(1.5rem, 3vw, 2.1rem); letter-spacing: -0.02em;
  margin: 0 0 12px; text-wrap: balance;
}
.wake-copy p { color: var(--text-dim); margin: 0; max-width: 46ch; text-wrap: pretty; }
.wake-bar { height: 2px; background: var(--line); border-radius: 2px; margin-top: 26px; max-width: 300px; overflow: clip; }
.wake-bar i { display: block; height: 100%; width: 25%; background: linear-gradient(90deg, var(--flag), var(--flag-soft)); border-radius: 2px; transform: translateX(calc(var(--step, 0) * 100%)); transition: transform 0.45s var(--ease-out); }

.wake-orbit { display: flex; justify-content: center; }
.wake-orbit svg { width: min(100%, 380px); height: auto; }
.wake-orbit .oring { stroke: var(--line-strong); stroke-width: 1; fill: none; }
.wake-orbit .odraw {
  stroke: var(--flag); stroke-width: 2.5; fill: none; stroke-linecap: round;
  filter: drop-shadow(0 0 6px var(--flag-dim));
  transform: rotate(-90deg); transform-origin: center;
}
.wake-orbit .odash { stroke: var(--glass-border); stroke-width: 1; fill: none; stroke-dasharray: 2 7; animation: orbit-spin 46s linear infinite reverse; transform-origin: center; transform-box: fill-box; }
.wake-orbit .ostep { fill: var(--surface-2); stroke: var(--line-strong); stroke-width: 1; transition: fill 0.4s, stroke 0.4s; }
.wake-orbit .ostep.on { fill: var(--flag); stroke: var(--flag); filter: drop-shadow(0 0 5px var(--flag-dim)); }
.wake-orbit .otravel { animation: orbit-spin 14s linear infinite; transform-origin: center; transform-box: view-box; }
.wake-orbit .otraveller { fill: var(--gust); filter: drop-shadow(0 0 6px var(--gust-dim)); }
.wake-orbit .onum { font-family: var(--font-heading); font-size: 46px; font-weight: 600; fill: var(--text); }
.wake-orbit .osub { font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.2em; fill: var(--text-faint); }
@keyframes orbit-spin { to { transform: rotate(360deg); } }

/* ---- clock card ---- */
.clock-card {
  display: inline-flex; flex-direction: column; gap: 5px;
  background: var(--glass); border: 1px solid var(--glass-border);
  border-radius: 14px; padding: 15px 20px; margin-top: 28px;
  font-family: var(--font-mono);
}
.clock-time { font-size: 1.35rem; font-weight: 600; letter-spacing: 0.06em; font-variant-numeric: tabular-nums; }
.clock-time small { font-size: 0.7rem; color: var(--text-faint); letter-spacing: 0.15em; margin-left: 8px; }
.clock-next { font-size: 0.8rem; color: var(--gust); }
.clock-bar { height: 3px; border-radius: 3px; background: var(--line); overflow: clip; margin-top: 6px; }
.clock-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--gust), var(--flag)); border-radius: 3px; width: var(--wake-fill, 0%); transition: width 1s linear; }

/* ---- mesh graph (index) + fleet topology ---- */
.mesh-wrap { display: flex; justify-content: center; margin-block: 10px 40px; }
.mesh-svg { width: min(100%, 560px); height: auto; }

.topo-board {
  position: relative; overflow: clip;
  background:
    radial-gradient(ellipse 70% 60% at 50% 46%, color-mix(in srgb, var(--gust) 4%, transparent), transparent 70%),
    var(--surface);
  border: 1px solid var(--glass-border); border-radius: 20px;
  padding: 10px 10px 0;
}
.topo-scroll { overflow-x: auto; overflow-y: clip; }
.topo-svg { width: 100%; min-width: 760px; height: auto; display: block; }
.topo-detail {
  border-top: 1px solid var(--line);
  padding: 13px 16px; min-height: 54px;
  font-size: 0.88rem; color: var(--text-dim);
  display: flex; align-items: center; flex-wrap: wrap; row-gap: 2px;
}
.topo-detail strong { color: var(--text); }
.topo-detail .sep { color: var(--text-faint); padding-inline: 9px; }
.topo-detail code { font-size: 0.8rem; }

.sweep {
  fill: color-mix(in srgb, var(--gust) 4%, transparent);
  mix-blend-mode: screen; pointer-events: none;
  filter: blur(16px);
  transform-box: view-box; transform-origin: 460px 285px;
  animation: sweep-spin 12s linear infinite;
}
@keyframes sweep-spin { to { transform: rotate(360deg); } }

.hostarc { fill: none; stroke: var(--line); stroke-width: 1; stroke-dasharray: 3 6; }
.hostlabel { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: 0.14em; fill: var(--text-faint); text-anchor: middle; }

/* ---- host cluster boxes: static texture behind Gale's own live spokes.
   Structure sourced from Tidal's own published /fleet map (cited in copy);
   these lines carry no live/pending claim of Gale's own -- that signal
   lives only on .edge below. ---- */
.aurora-wrap { pointer-events: none; }
.aurora {
  fill: color-mix(in srgb, var(--gust) 7%, transparent);
  filter: blur(70px); mix-blend-mode: screen;
  animation: aurora-drift 16s ease-in-out infinite alternate;
}
@keyframes aurora-drift {
  from { transform: translate(-18px, -8px) scale(1); }
  to { transform: translate(18px, 10px) scale(1.08); }
}
.hostbox { fill: color-mix(in srgb, var(--surface-2) 55%, transparent); stroke: var(--line); stroke-width: 1; }
.hostbox-gale { stroke: color-mix(in srgb, var(--flag) 35%, var(--line)); }
.meshline { stroke: var(--line); stroke-width: 0.75; opacity: 0.55; pointer-events: none; }

.trunks { pointer-events: none; }
.trunk-wash { fill: none; stroke: url(#gustGrad); stroke-width: 5; stroke-dasharray: 16 11; opacity: 0.25; }
.trunk-glow { fill: none; stroke: var(--gust); stroke-width: 1; opacity: 0.18; filter: blur(3px); }
.trunk-line { fill: none; stroke: var(--gust-dim); stroke-width: 1; }
.trunk-flow {
  fill: var(--gust); filter: drop-shadow(0 0 5px var(--gust-dim));
  offset-rotate: 0deg; animation: trunk-run 3.4s linear infinite;
}
@keyframes trunk-run { from { offset-distance: 0%; opacity: 0; } 8% { opacity: 1; } 92% { opacity: 1; } to { offset-distance: 100%; opacity: 0; } }
.gust-stop-a, .gust-stop-b, .gust-stop-c { animation: gust-cycle 9s ease-in-out infinite; }
.gust-stop-b { animation-delay: -3s; }
.gust-stop-c { animation-delay: -6s; }
@keyframes gust-cycle {
  0%, 100% { stop-color: var(--gust); }
  50% { stop-color: var(--flag-soft); }
}

.scan {
  fill: none; stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 2 5;
  transform-box: fill-box; transform-origin: center; opacity: 0.6;
  animation: scan-spin 8s linear infinite;
}
.scan.ccw { animation-direction: reverse; }
.scan-hub { stroke: var(--flag-dim); animation-duration: 11s; }
@keyframes scan-spin { to { transform: rotate(360deg); } }

.edge { stroke-width: 1; fill: none; transition: opacity 0.35s, stroke-width 0.35s; }
.edge.up { stroke: color-mix(in srgb, var(--ok) 52%, transparent); stroke-dasharray: 3 5; animation: edge-flow 2.8s linear infinite; }
.edge.pending { stroke: var(--line-strong); stroke-dasharray: 2 5; opacity: 0.55; }
@keyframes edge-flow { to { stroke-dashoffset: -16; } }

.photon {
  stroke: var(--gust); stroke-width: 2.1; stroke-linecap: round; fill: none;
  stroke-dasharray: 10 470; opacity: 0.75;
  filter: drop-shadow(0 0 4px var(--gust-dim));
  animation: photon-run 4.6s linear infinite;
  pointer-events: none;
}
@keyframes photon-run { to { stroke-dashoffset: -480; } }

.node { cursor: pointer; transition: opacity 0.35s; outline: none; }
.node .core { transition: r 0.25s, filter 0.3s, opacity 0.35s; }
.node.up .core { fill: var(--ok); color: var(--ok); filter: drop-shadow(0 0 5px color-mix(in srgb, var(--ok) 55%, transparent)); }
.node.pending .core { opacity: 0.5; }
.node.pending .pring { fill: none; stroke: var(--text-faint); stroke-width: 1; stroke-dasharray: 2 3; opacity: 0.7; }
.node .nlabel {
  font-family: var(--font-mono); font-size: 9.5px; letter-spacing: 0.06em;
  fill: var(--text-faint); text-anchor: middle; pointer-events: none;
  transition: fill 0.3s;
}
.node.up .nlabel { fill: var(--text-dim); }
.node:hover .core, .node:focus-visible .core, .node.focus .core { filter: drop-shadow(0 0 10px color-mix(in srgb, currentColor 75%, transparent)); }
.node:hover .nlabel, .node:focus-visible .nlabel, .node.focus .nlabel { fill: var(--text); }

.ping {
  fill: none; stroke: var(--ok); stroke-width: 1.1; opacity: 0;
  transform-box: fill-box; transform-origin: center;
  animation: ping-ring 3s cubic-bezier(0, 0, 0.2, 1) infinite;
  animation-delay: calc(var(--i, 0) * -0.7s);
  pointer-events: none;
}
.hub .ping, .hubping { stroke: var(--flag); }
@keyframes ping-ring {
  0% { transform: scale(0.4); opacity: 0.65; }
  70% { transform: scale(2.8); opacity: 0; }
  100% { transform: scale(2.8); opacity: 0; }
}

.hub { cursor: pointer; outline: none; }
.hubring { fill: none; stroke: var(--flag); stroke-width: 1.2; opacity: 0.6; }
.hubcore { fill: var(--flag); filter: drop-shadow(0 0 10px var(--flag-dim)); }
.hublabel { fill: var(--text); font-weight: 600; font-size: 10px; }

/* model-family colours (fleet convention); `color` mirrors `fill` so
   glow rules can key off currentColor */
.node[data-model="Claude"] .core { fill: var(--m-claude); color: var(--m-claude); }
.node[data-model="GLM"] .core { fill: var(--m-glm); color: var(--m-glm); }
.node[data-model="GPT"] .core { fill: var(--m-gpt); color: var(--m-gpt); }
.node[data-model="Muse"] .core { fill: var(--m-muse); color: var(--m-muse); }

/* host filtering: one rule per host; JS just sets data-filter on the svg root */
.topo[data-filter="Tidal host"] .hosted:not([data-host="Tidal host"]),
.topo[data-filter="Beacon host"] .hosted:not([data-host="Beacon host"]),
.topo[data-filter="Mountain host"] .hosted:not([data-host="Mountain host"]),
.topo[data-filter="Gale host"] .hosted:not([data-host="Gale host"]) { opacity: 0.12; }
.topo[data-filter]:not([data-filter="All"]) .clusterbox:not(.galebox) .meshline,
.topo[data-filter]:not([data-filter="All"]) .trunks { opacity: 0.12; transition: opacity 0.35s; }

.legend { display: flex; gap: 20px; flex-wrap: wrap; margin-top: 26px; font-size: 0.82rem; color: var(--text-dim); }
.legend .led { width: 9px; height: 9px; border-radius: 50%; display: inline-block; margin-right: 8px; vertical-align: baseline; }
.legend .led.up { background: var(--ok); box-shadow: 0 0 7px var(--ok); }
.legend .led.pending { background: var(--text-faint); }

/* ---- filter chips ---- */
.filter-row { display: flex; gap: 9px; flex-wrap: wrap; margin-bottom: 22px; }
.chip {
  font-family: var(--font-mono); font-size: 0.78rem; letter-spacing: 0.03em;
  color: var(--text-dim); background: var(--surface); border: 1px solid var(--line);
  border-radius: 999px; padding: 7px 16px; cursor: pointer;
  transition: color 0.2s, border-color 0.2s, background 0.2s, transform 0.2s;
}
.chip:hover { color: var(--text); border-color: var(--line-strong); transform: translateY(-1px); }
.chip[aria-pressed="true"] {
  color: var(--text); border-color: color-mix(in srgb, var(--flag) 60%, transparent);
  background: color-mix(in srgb, var(--flag) 13%, transparent);
}

/* ---- peer grid (index) ---- */
.peer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(152px, 1fr)); gap: 10px; }
.peer {
  border: 1px solid var(--line); border-radius: 12px; padding: 12px 14px;
  background: var(--surface); font-size: 0.88rem;
  display: flex; align-items: center; gap: 10px;
  transition: transform 0.2s var(--ease-out), background 0.2s, border-color 0.2s;
}
.peer:hover, .peer.hot { transform: translateY(-2px); background: var(--surface-2); border-color: var(--line-strong); }
.peer .led { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.peer.up .led { background: var(--ok); box-shadow: 0 0 8px var(--ok); animation: led-pulse 2.6s ease-in-out infinite; animation-delay: calc(var(--i, 0) * -0.35s); }
.peer.pending .led { background: var(--text-faint); }
.peer.pending { color: var(--text-faint); }
@keyframes led-pulse { 50% { box-shadow: 0 0 0 5px color-mix(in srgb, var(--ok) 22%, transparent); } }

/* ---- roster (fleet page) ---- */
.roster-group { margin-bottom: 40px; }
.roster-group:last-child { margin-bottom: 0; }
.roster-host {
  font-family: var(--font-heading); font-size: 1.18rem; font-weight: 600;
  margin: 0 0 16px; display: flex; align-items: baseline; gap: 12px;
}
.roster-count { font-family: var(--font-mono); font-size: 0.72rem; font-weight: 400; color: var(--text-faint); letter-spacing: 0.06em; }
.member-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(235px, 1fr)); gap: 11px; }
.member-card {
  border: 1px solid var(--line); border-radius: 14px; padding: 15px 16px;
  background: var(--surface); font-size: 0.88rem;
  transition: transform 0.22s var(--ease-out), background 0.22s, border-color 0.22s;
}
.member-card:hover { transform: translateY(-3px); background: var(--surface-2); border-color: var(--line-strong); }
.member-card.hub { border-color: color-mix(in srgb, var(--flag) 45%, transparent); }
.member-top { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.member-top .led { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.member-card.up .led { background: var(--ok); box-shadow: 0 0 8px var(--ok); }
.member-card.pending .led { background: var(--text-faint); }
.member-card.pending strong { color: var(--text-dim); }
.model-chip {
  margin-left: auto; font-family: var(--font-mono); font-size: 0.66rem;
  letter-spacing: 0.06em; border: 1px solid; border-radius: 999px; padding: 2px 9px;
}
.member-role { color: var(--text-dim); margin-bottom: 5px; font-size: 0.86rem; }
.member-listener { margin-bottom: 3px; }
.member-listener code { font-size: 0.74rem; color: var(--gust); }
.member-state { font-size: 0.74rem; color: var(--text-faint); }

/* ---- activity log ---- */
.log-list { list-style: none; margin: 0; padding: 0 0 0 26px; border-left: 1px solid var(--line); max-width: 820px; }
.log-list li {
  position: relative; padding: 20px 0 20px 26px;
  border-bottom: 1px dashed var(--line);
  transition: background 0.25s;
}
.log-list li:last-child { border-bottom: 0; }
.log-list li::before {
  content: ""; position: absolute; left: -31px; top: 27px;
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--surface-2); border: 2px solid var(--flag);
  transition: background 0.25s, box-shadow 0.25s;
}
.log-list li:hover::before { background: var(--flag); box-shadow: 0 0 10px var(--flag-dim); }
.log-list time { font-family: var(--font-mono); font-size: 0.76rem; color: var(--text-faint); letter-spacing: 0.04em; }
.log-list p { margin: 6px 0 0; color: var(--text-dim); line-height: 1.55; text-wrap: pretty; }
.log-list p strong { color: var(--text); font-weight: 600; margin-right: 6px; }

/* ---- two-column info blocks ---- */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4vw, 48px); }
@media (max-width: 880px) { .two-col { grid-template-columns: 1fr; } }
.two-col h3 { font-family: var(--font-heading); font-size: 1.12rem; font-weight: 600; margin: 0 0 8px; }
.two-col p { color: var(--text-dim); font-size: 0.95rem; margin: 0 0 14px; text-wrap: pretty; }

.mono-list { list-style: none; padding: 0; margin: 14px 0 0; }
.mono-list li {
  font-size: 0.87rem; color: var(--text-dim);
  border-bottom: 1px solid var(--line); padding: 8px 2px;
  display: flex; justify-content: space-between; gap: 14px;
}
.mono-list li:last-child { border-bottom: 0; }
.mono-list code { font-size: 0.78rem; white-space: nowrap; }

/* ---- buttons ---- */
.cta-row { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 26px; }
.btn {
  display: inline-flex; align-items: center; gap: 9px;
  font-family: var(--font-mono); font-size: 0.8rem; letter-spacing: 0.05em;
  color: var(--text); text-decoration: none;
  border: 1px solid var(--line-strong); border-radius: 10px;
  padding: 11px 18px; background: var(--glass);
  transition: border-color 0.25s, background 0.25s, transform 0.25s var(--ease-out), box-shadow 0.25s;
}
.btn:hover { border-color: color-mix(in srgb, var(--flag) 55%, transparent); background: color-mix(in srgb, var(--flag) 9%, transparent); transform: translateY(-2px); box-shadow: 0 10px 26px rgba(0, 0, 0, 0.3); text-decoration: none; }
.btn.primary { border-color: color-mix(in srgb, var(--flag) 55%, transparent); background: color-mix(in srgb, var(--flag) 13%, transparent); }
.btn svg { flex: none; }

/* ---- footer ---- */
footer.site { border-top: 1px solid var(--line); margin-top: 40px; background: color-mix(in srgb, var(--bg-deep) 70%, transparent); }
footer.site .wrap {
  padding-block: 44px; display: grid;
  grid-template-columns: 1.2fr 1fr 1fr; gap: 28px;
  font-size: 0.85rem; color: var(--text-faint);
}
@media (max-width: 760px) { footer.site .wrap { grid-template-columns: 1fr; gap: 20px; } }
footer.site .fbrand { font-family: var(--font-heading); font-weight: 600; font-size: 1.05rem; color: var(--text); margin-bottom: 8px; }
footer.site h4 { font-family: var(--font-mono); font-size: 0.7rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-faint); margin: 0 0 10px; font-weight: 500; }
footer.site ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
footer.site a { color: var(--text-dim); text-decoration: none; }
footer.site a:hover { color: var(--gust); text-decoration: underline; text-underline-offset: 3px; }

/* ---- reveal system: slide-only, additive (no .js => fully visible) ---- */
.reveal { transition: transform 0.7s var(--ease-expo); will-change: transform; }
.js .reveal { transform: translateY(20px); transition-delay: calc(var(--i, 0) * 70ms); }
.js .reveal.in-view { transform: none; }

/* ---- ops status board (status.html) ---- */
.ops-main { max-width: 1320px; margin-inline: auto; padding-inline: 24px; padding-block: 40px 60px; }
.ops-head {
  display: flex; justify-content: space-between; align-items: flex-end; gap: 24px;
  flex-wrap: wrap; margin-bottom: 28px; padding-bottom: 24px; border-bottom: 1px solid var(--line);
}
.ops-title { font-family: var(--font-heading); font-weight: 600; font-size: clamp(1.7rem, 3vw, 2.2rem); margin: 10px 0 10px; }
.ops-head .lede { max-width: 62ch; }

.freshness {
  display: inline-flex; align-items: center; gap: 9px; font-family: var(--font-mono);
  font-size: 0.8rem; color: var(--text-dim); background: var(--surface); border: 1px solid var(--line);
  border-radius: 999px; padding: 8px 16px; white-space: nowrap;
}
.freshness-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--text-faint); flex: none; }
.freshness[data-state="live"] .freshness-dot { background: var(--ok); box-shadow: 0 0 8px var(--ok); animation: led-pulse 2.6s ease-in-out infinite; }
.freshness[data-state="stale"] { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 45%, var(--line)); }
.freshness[data-state="stale"] .freshness-dot { background: var(--warn); }
.freshness[data-state="down"] { color: var(--flag-soft); border-color: color-mix(in srgb, var(--flag) 45%, var(--line)); }
.freshness[data-state="down"] .freshness-dot { background: var(--flag); }

.ops-board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.ops-panel {
  background: var(--surface); border: 1px solid var(--line); border-radius: 16px;
  padding: 20px 22px 22px;
}
.ops-panel.span-full { grid-column: 1 / -1; }
@media (max-width: 980px) { .ops-board { grid-template-columns: 1fr; } }
.panel-title {
  font-family: var(--font-heading); font-weight: 600; font-size: 1.02rem;
  margin: 0 0 16px; padding-bottom: 12px; border-bottom: 1px solid var(--line);
}
.panel-title span { color: var(--text-faint); font-family: var(--font-mono); font-size: 0.85rem; font-weight: 400; }

/* vitals: big tiles with a threshold-coloured meter bar */
.vitals-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; }
.vital {
  border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px;
  background: var(--surface-2); display: flex; flex-direction: column; gap: 6px;
}
.vital-label { font-family: var(--font-mono); font-size: 0.72rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-faint); }
.vital-value { font-family: var(--font-heading); font-size: 1.65rem; font-weight: 600; line-height: 1; }
.vital[data-level="warn"] .vital-value { color: var(--warn); }
.vital[data-level="crit"] .vital-value { color: var(--flag-soft); }
.vital-sub { font-size: 0.78rem; color: var(--text-faint); }

.meter { height: 5px; border-radius: 3px; background: var(--line); overflow: clip; }
.meter i { display: block; height: 100%; border-radius: 3px; background: var(--ok); transition: width 0.6s var(--ease-out); }
.meter[data-level="warn"] i { background: var(--warn); }
.meter[data-level="crit"] i { background: var(--flag); }

/* key/value lists */
.kv-list { display: grid; grid-template-columns: auto 1fr; gap: 9px 14px; margin: 0; font-size: 0.88rem; }
.kv-list dt { color: var(--text-faint); }
.kv-list dd { margin: 0; text-align: right; color: var(--text-dim); font-family: var(--font-mono); font-size: 0.85rem; }

/* per-core mini bar chart */
.core-grid { display: flex; gap: 4px; align-items: flex-end; height: 74px; }
.core { flex: 1; height: 100%; background: var(--surface-2); border-radius: 3px; display: flex; align-items: flex-end; overflow: clip; }
.core i { display: block; width: 100%; background: var(--ok); transition: height 0.6s var(--ease-out); }
.core[data-level="warn"] i { background: var(--warn); }
.core[data-level="crit"] i { background: var(--flag); }

/* generic data table used by network/services/ports panels */
.ops-table { width: 100%; border-collapse: collapse; font-size: 0.86rem; }
.ops-table th {
  text-align: left; font-family: var(--font-mono); font-size: 0.68rem; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--text-faint); font-weight: 500; padding: 0 10px 8px 0;
  border-bottom: 1px solid var(--line);
}
.ops-table td { padding: 8px 10px 8px 0; border-bottom: 1px solid var(--line); color: var(--text-dim); vertical-align: middle; }
.ops-table tr:last-child td { border-bottom: none; }
.ops-table code { font-size: 0.82rem; color: var(--text); }
.mono-dim { font-family: var(--font-mono); font-size: 0.78rem; color: var(--text-faint); }
.mini-note { font-size: 0.8rem; color: var(--text-faint); margin: 12px 0 0; }
.mini-toggle {
  margin-top: 12px; font-family: var(--font-mono); font-size: 0.76rem; color: var(--gust);
  background: none; border: none; cursor: pointer; padding: 0; text-decoration: underline; text-underline-offset: 3px;
}

.pill {
  display: inline-block; font-family: var(--font-mono); font-size: 0.72rem; letter-spacing: 0.04em;
  padding: 2px 9px; border-radius: 999px; border: 1px solid var(--line-strong);
  color: var(--ok); background: var(--ok-dim);
}
.pill[data-level="ok"] { color: var(--ok); background: color-mix(in srgb, var(--ok) 16%, transparent); border-color: var(--ok-dim); }
.pill[data-level="warn"] { color: var(--warn); background: color-mix(in srgb, var(--warn) 16%, transparent); border-color: var(--warn-dim); }
.pill[data-level="crit"] { color: var(--flag-soft); background: color-mix(in srgb, var(--flag) 16%, transparent); border-color: var(--flag-dim); }
